In this paper, we consider the following Riemannian Constrained Optimization Problem (RCOP):
\begin{equation}\tag{RCOP} \label{RCOP} 
	\begin{array}{ll}
		\underset{x \in \mathcal{M}}{\min} & f(x) \\
		\text { s.t. } & h(x)=0, \text{ and }  g(x) \leq 0,\\
	\end{array}
\end{equation}
where $\mathcal{M}$ is a connected, complete $d$-dimensional Riemannian manifold and $f \colon \mathcal{M}\to \mathbb{R}, h\colon\mathcal{M}\to \mathbb{R}^{l}$, and $g\colon\mathcal{M}\to \mathbb{R}^{m}$ are smooth functions.


Let us briefly review some concepts from Riemannian geometry, following the notation of \cite{boumal2022intromanifolds}.
$\mathcal{M}$ denotes a finite-dimensional smooth manifold.
Let $p \in \mathcal{M}$ and $T_p \mathcal{M}$ be the tangent space at $p$ with $0_{p}$ being its zero element.
We use a canonical identification $ T_{p} \mathcal{E}\cong \mathcal{E}$ for a vector space $ \mathcal{E} $ and $p \in \mathcal{E}$.
A vector field is a map $V \colon \mathcal{M} \to T \mathcal{M}$ with $V(p) \in T_{p} \mathcal{M}$, where $T \mathcal{M}:=\bigcup_{p \in \mathcal{M}} T_p \mathcal{M}$ is the tangent bundle. 
$\mathfrak{X}(\mathcal{M})$ denotes the set of all smooth vector fields defined on $\mathcal{M}$.
Furthermore, $\mathcal{M}$ is a Riemannian manifold if it is equipped with a Riemannian metric, that is, a choice of inner product $\langle\cdot, \cdot\rangle_p \colon T_p \mathcal{M} \times T_p \mathcal{M} \to \mathbb{R} $ for each tangent space at $p$ on $\mathcal{M}$ such that for all $V, W \in \mathfrak{X}(\mathcal{M})$, the map
\begin{equation}\label{eq:RiemannianMetric}
	p \mapsto\langle V(p), W(p)\rangle_p
\end{equation}
is a smooth function from $\mathcal{M}$ to $\mathbb{R}$.
Riemannian metric induces the norm $\|\xi\|_p:=\sqrt{\langle\xi, \xi\rangle_p}$ for $\xi \in T_p \mathcal{M}$.
We often omit the subscript $p$ if it is clear from the context.
Throughout this paper, we assume that all the manifolds involved are \emph{connected} and \emph{complete}.
Given a curve segment on $\mathcal{M}$, $c:[a, b] \rightarrow \mathcal{M}$, the length of $c$ is defined as 
$
L(c):=\int_a^b \| \dot{c}(t)\|_{c(t)} \mathrm{d} t,
$
where $\dot{c}(t) \in T_{c(t)} \mathcal{M}$ is the velocity vector of $c$ at $t$.
Since $\mathcal{M}$ is connected, there exists a curve segment connecting any pair of points $p,q \in \mathcal{M}$.
Indeed, $\mathcal{M}$ is a metric space under the Riemannian distance $d(p, q):=\inf_{c} L(c) $ where the infimum is taken over all curve segments joining $p $ to $q $ \cite[Thm. 2.55]{lee2018}.
For two manifolds $\mathcal{M}_1, \mathcal{M}_2$ and a smooth map $F \colon \mathcal{M}_1 \to \mathcal{M}_2$, the differential of $F$ at $p \in \mathcal{M}_1$ is a linear operator denoted as $\mathcal{D} F(p) \colon T_p \mathcal{M}_1 \to T_{F(p)} \mathcal{M}_2$.
Let $\mathfrak{F}(\mathcal{M})$ be the set of all smooth \emph{scalar fields} (or say real-valued functions) $f\colon \mathcal{M} \to \mathbb{R}$.
The Riemannian gradient of $f$ at $p$, $\operatorname{grad} f(p)$, is defined as the unique element of $T_p \mathcal{M}$ that satisfies $\langle \xi, \operatorname{grad} f(p)\rangle_p = \mathcal{D} f(p)[\xi]$ for all $\xi \in T_p \mathcal{M}$, where $\mathcal{D} f(p) \colon T_p \mathcal{M} \to T_{f(p)} \mathbb{R} \cong \mathbb{R}$.
Note that for any $f \in \mathfrak{F}(\mathcal{M})$, the gradient vector field $x \mapsto \operatorname{grad} f(x)$ is a smooth vector field on $\mathcal{M}$, i.e., $\operatorname{grad} f \in \mathfrak{X}(\mathcal{M})$.
A retraction $\mathrm{R} \colon T \mathcal{M} \to \mathcal{M}$ is a smooth map such that
$\mathrm{R}_{p}\left(0_{p}\right)=p$ and $\mathcal{D} \mathrm{R}_{p}\left(0_{p}\right) =\operatorname{id}_{T_p \mathcal{M}}$, i.e., the identity map on $T_{p} \mathcal{M}$, where $\mathrm{R}_{p}$ is the restriction of $\mathrm{R}$ to $T_{p} \mathcal{M}$ and $\mathcal{D} \mathrm{R}_{p}\left(0_{p}\right) \colon T_{0_p} (T_p \mathcal{M}) \cong T_p \mathcal{M} \to T_{p} \mathcal{M}$ is the differential of $\mathrm{R}_{p}$ at $0_{p}$.
One theoretically perfect type of retraction is the exponential map, denoted as $\operatorname{Exp}$. Since $\mathcal{M}$ is complete, the exponential map is well-defined on the whole tangent bundle.
Let $\operatorname{Exp}_p\colon T_p \mathcal{M} \rightarrow \mathcal{M}$ be the exponential map at $p$; then $t \mapsto \operatorname{Exp}_p(t \xi)$ is the unique geodesic that passes through $p$ with velocity $\xi \in T_p \mathcal{M}$ when $t=0$.

\subsection{Riemannian Newton Method}\label{subsec:RiemannianNewton}

The Newton method is a powerful tool for finding the zeros of nonlinear functions in the Euclidean setting.
The generalized Newton method has been studied in the Riemannian setting; it aims to find a \emph{singularity} for the vector field $F \in \mathfrak{X}(\mathcal{M})$, i.e., a point $p \in \mathcal{M}$ such that,
\begin{equation}\label{eq:Singularity}
	F(p)=0_{p} \in T_p \mathcal{M}.
\end{equation}
Let $\nabla$ be the Levi-Civita connection on $\mathcal{M}$, i.e., the unique symmetric connection compatible with the Riemannian metric.
The covariant derivative $\nabla F$ assigns each point $p \in \mathcal{M}$ a linear operator $\nabla F(p)\colon T_{p}\mathcal{M}\to T_{p}\mathcal{M}$. 
In particular, the Riemannian Hessian of $f \in \mathfrak{F}(\mathcal{M})$ at $p$ is a self-adjoint operator on $T_{p} \mathcal{M}$, defined as $\operatorname{Hess} f(p):=\nabla (\operatorname{grad}f)(p).$


In this section, we will give a comprehensive interpretation of the Riemannian interior point method.
Following common usage in the interior-point literature, big letters denote the associated diagonal matrix, e.g., $Z =\operatorname{diag}(z_{1}, \ldots, z_{m})$ with $z \in \mathbb{R}^{m}$. $e$ denotes the all-ones vector, and $0$ stands for zero vector/matrix with proper dimensions.

\subsection{KKT Vector Field and Its Covariant Derivative}

The Lagrangian function of (\ref{RCOP}) is
\begin{equation*}
	\mathcal{L}(x, y, z):=f(x)+\sum_{i=1}^l y_i h_i(x)+\sum_{i=1}^m z_i g_i(x),
\end{equation*}
where $y \in \mathbb{R}^l$ and $z \in \mathbb{R}^m$ are Lagrange multipliers corresponding to the equality and
inequality constraints, respectively.
With respect to the variable $x$, $\mathcal{L}(\cdot, y, z)$ is a real-valued function defined on $\mathcal{M}$, and its Riemannian gradient is
\begin{equation*}
\operatorname{grad}_{x} \mathcal{L}(x, y, z)=\operatorname{grad} f(x) + \sum_{i =1 }^{l} y_{i} \operatorname{grad} h_{i}(x) + \sum_{i =1 }^{m} z_{i} \operatorname{grad} g_{i}(x),
\end{equation*}
where $\{\operatorname{grad} h_{i}(x)\}_{i=1}^{l}$ and $ \{\operatorname{grad} g_{i}(x)\}_{i=1}^{m}$ are the gradients of the component functions of $h$ and $g$. 
The Riemannian KKT conditions (e.g., see \cite[Definition 2.3]{liu2020simple} or \cite{yang2014optimality}) for (\ref{RCOP}) are given by
\begin{equation}\label{eq:KKTConditions}
	\operatorname{grad}_{x} \mathcal{L}(x, y, z) =0_{x}; \;
	h(x) =0 ,
	g(x) \leq 0 , 
	z  \geq 0; \;
	Z g(x) =0.
\end{equation}
The above conditions can be written in terms of slack variables $\mathbb{R}^{m} \ni s:=-g(x)$, as
\begin{equation}\label{eq:KKTVectorField}
	F(w):=\left(\begin{array}{l}
		\operatorname{grad}_{x} \mathcal{L}(x, y, z) \\
		 h(x) \\
		g(x)+s \\
		Z S e
	\end{array}\right)=0_{w}
	=\left(\begin{array}{l}
		0_{x} \\
		0\\
		0\\
		0
	\end{array}\right) \in T_w \mathcal{N},
\end{equation}
and $(z,s) \geq 0,$
where $w:=(x, y, z,s) \in \mathcal{N}:=\mathcal{M}\times \mathbb{R}^{l} \times \mathbb{R}^{m} \times \mathbb{R}^{m}$.
Here, we have generated a vector field $F$ in (\ref{eq:KKTVectorField}) on the product manifold $\mathcal{N}$, i.e.,
for any $w\in \mathcal{N}$, 
$
F(w) \in
T_{w} \mathcal{N} \cong T_{x} \mathcal{M} \times \mathbb{R}^{l} \times \mathbb{R}^{m} \times \mathbb{R}^{m}.
$
We will call $F \colon \mathcal{N} \to T\mathcal{N} $ in (\ref{eq:KKTVectorField}) above the \emph{KKT vector field} for (\ref{RCOP}).
Note that for $\xi=\left(\xi_x, \xi_y, \xi_z, \xi_s\right) \in T_{w} \mathcal{N} $,
\begin{equation}\label{eq:barR}
	\bar{\mathrm{R}}_{w}(\xi):=(\mathrm{R}_{x}(\xi_{x}), y+\xi_{y}, z+\xi_{z}, s+\xi_{s})
\end{equation}
is a well-defined retraction on the product manifold $\mathcal{N}$ as long as $\mathrm{R}$ is a retraction on $\mathcal{M}$.

Now, we aim to find a singularity of the KKT vector field $F$ on $\mathcal{N}$ under some nonnegative constraints $(z,s) \geq 0$.
If the Riemannian Newton method is to be applied to (\ref{eq:KKTVectorField}), we must formulate the covariant derivative of $F$ at an arbitrary $w \in \mathcal{N}$. Before that, we need some new symbols.
Fixing a point $x \in \mathcal{M}$, we can define two linear operators $\mathcal{H}_{x}\colon \mathbb{R}^{l} \rightarrow T_{x} \mathcal{M}$ and $\mathcal{G}_{x}\colon \mathbb{R}^{m} \rightarrow T_{x} \mathcal{M}$ by
\begin{equation}\label{defn:HxGx}
	\mathcal{H}_x [v]:=\sum_{i=1}^l v_i \operatorname{grad} h_i(x), \quad \mathcal{G}_x [u]:=\sum_{i=1}^m u_i \operatorname{grad} g_i(x),
\end{equation}
respectively.
Then, for $\mathcal{H}_{x}$, its adjoint operator $\mathcal{H}_x^*\colon T_x \mathcal{M} \rightarrow \mathbb{R}^l$ is given by
\begin{equation*}
	\mathcal{H}_x^* [\xi]=\left(\left\langle\operatorname{grad} h_1(x), \xi\right\rangle_x, \cdots,\left\langle\operatorname{grad} h_l(x), \xi\right\rangle_x\right)^T.
\end{equation*}
Also, $\mathcal{G}_x^*\colon T_x \mathcal{M} \rightarrow \mathbb{R}^m$ with $\mathcal{G}_x^* [\xi]=\left(\left\langle\operatorname{grad} g_1(x), \xi\right\rangle_x, \cdots,\left\langle\operatorname{grad} g_m(x), \xi\right\rangle_x\right)^T$. 

Now, using the solutions of Exercises 5.4 and 5.13 on covariant derivatives of vector fields on product manifolds in monograph \cite{boumal2022intromanifolds}, the following results can be easily derived.
Given KKT vector field $F $ in (\ref{eq:KKTVectorField}) and $w \in \mathcal{N}$, the covariant derivative of $F$ at $w$ is the operator $\nabla F(w)\colon T_{w} \mathcal{N} \to T_{w} \mathcal{N}$ given by
\begin{equation}\label{eq:CovariantDerivativeKKTVectorField}
	\nabla F(w) [\Delta w] =
	\left(\begin{array}{l}
		\operatorname{Hess}_{x} \mathcal{L}(w) [\Delta x]
		+\mathcal{H}_{x} [\Delta y]
		+\mathcal{G}_{x} [\Delta z]\\
		\mathcal{H}_{x}^{*}[\Delta x]\\
		\mathcal{G}_{x}^{*}[\Delta x]+\Delta s\\
		Z \Delta s + S \Delta z
	\end{array}\right),
\end{equation}
where $\Delta w=(\Delta x, \Delta y, \Delta z, \Delta s) \in T_{w} \mathcal{N}$ and $\operatorname{Hess}_{x} \mathcal{L}(w)$ is the Riemannian Hessian of real-valued function $\mathcal{L}(\cdot, y, z)$.
Indeed,
$\operatorname{Hess}_{x} \mathcal{L}(w)\colon T_{x}\mathcal{M} \to T_{x}\mathcal{M}$ satisfies
\begin{equation}\label{eq:HessianLagrange}
	\operatorname{Hess}_{x} \mathcal{L}(w) =
	\operatorname{Hess} f(x)
	+\sum_{i=1}^{l} y_{i} \operatorname{Hess} h_{i}(x)
	+\sum_{i=1}^{m} z_{i} \operatorname{Hess} g_{i}(x),
\end{equation}
where $\{\operatorname{Hess} h_{i}(x)\}_{i=1}^{l}$ and $\{\operatorname{Hess} g_{i}(x)\}_{i=1}^{m}$ are Hessians of the component functions of $h$ and $g$.


Next, we will discuss an important result about the covariant derivative of the KKT vector field given in (\ref{eq:CovariantDerivativeKKTVectorField}).
Let $\mathbb{A}(x):=\left\{i \mid g_{i}(x)=0\right\}$ denote the active set at $x \in \mathcal{M}$.
A prior study on Riemannian optimality conditions \cite{yang2014optimality,bergmann2019intrinsic} showed that the following assumptions are meaningful.
We call them the \emph{standard Riemannian assumptions} for (\ref{RCOP}).
Note that the $x^{*}$ and $w^*$ in \ref{B3}-\ref{B5} all refer to those in \ref{B1}.


\setlist[assumptions,1]{label=\textbf{(A\arabic*)}}
\begin{assumptions}[leftmargin=9mm]
	\item {Existence.} There exists $w^*=(x^{*}, y^{*}, z^{*}, s^{*})$ satisfying the Riemannian KKT conditions (\ref{eq:KKTConditions}). Here, we introduce the slack variables $s^{*}:=-g(x^{*})$.
	\label{B1}	
%	\item {Smoothness of $ C^{2} $.} The functions $f, g,$ and $h$ are $ C^{2} $ on $\mathcal{M}$.
%	\label{B2}	
	\item {Linear Independence Constraint Qualification (LICQ).} \\ The set $\left\{\operatorname{grad} h_{i}(x^{*})\right\}_{i=1}^{l} \bigcup \left\{\operatorname{grad} g_{i}(x^{*})\right\}_{i \in \mathbb{A}(x^{*})}$ is linearly independent in $ T_{x^{*}}\mathcal{M}$.
	\label{B3}	
	\item {Strict complementarity.} $(z^{*})_{i}>0$ if $g_{i}(x^{*})=0$ for all $i=1, \cdots,m$.
	\label{B4}	
	\item {Second-order sufficiency.}
	$\left \langle\operatorname{Hess}_{x} \mathcal{L}(w^{*})[\xi], \xi\right\rangle>0$ for all nonzero $\xi \in T_{x^{*}}\mathcal{M}$ \\ satisfying $\left\langle\xi, \operatorname{grad} h_{i}(x^{*})\right\rangle=0 $ for $i=1,\dots,l,$ and
	$\left\langle\xi, \operatorname{grad} g_{i}(x^{*})\right\rangle=0$ for $ i \in \mathbb{A}(x^{*})$. 
	\label{B5}
\end{assumptions}


Applying the Riemannian Newton method directly to the KKT vector field $F: \mathcal{N} \rightarrow T \mathcal{N}$ results in the following Newton equation (see (\ref{eq:StandardNewtonEquation}) without iteration count $k$) at each iteration:
\begin{equation}\label{eq:OriginalNewtonEquation}
	\nabla F(w) [\Delta w]+F(w)=0.
\end{equation}
As with the usual interior point method in the Euclidean setting, once the iterates reach the boundary of the feasible region, they are forced to stick to it \cite[P6]{wright1997primal}.
For the iterates to maintain a sufficient distance from the boundary, we introduce a perturbed complementary equation with some barrier parameter $\mu>0$ and define the \textit{perturbed KKT vector field}:
\begin{equation}\label{eq:perturbedKKTvectorfield}
	F_{\mu}(w):=F(w)-\mu \hat{e}, \text { and } \hat{e}:=\hat{e}(w):=\left(0_x, 0,0, e\right).
\end{equation}
Notice that the perturbation term $\hat{e}$, indeed, is a special vector field on $\mathcal{N}$, not a constant, because $0_x$ is essentially dependent on $w$ and/or $x$.
In fact, the covariant derivative of the perturbed KKT vector field is the same as that of the original. From the linearity of the connection $\nabla$, for any $w \in \mathcal{N}$ and any $\mu>0$, we have 
\begin{equation}\label{eq:NabulaperturbedKKTvectorfield}
	\nabla F_{\mu}(w)=\nabla F(w)-\mu \nabla \hat{e}(w)=\nabla F(w),
\end{equation}
where the last equity comes from $\nabla \hat{e}(w) [\Delta w]=\left(0_x, 0,0,0\right)$ for all $\Delta w \in T_w \mathcal{N}$.
Applying the Riemannian Newton method to perturbed KKT vector field $F_{\mu}(w)$ yields the \emph{perturbed Newton equation}: $\nabla F_{\mu}(w) [\Delta w]+F_{\mu}(w)=0$. 
From (\ref{eq:perturbedKKTvectorfield}) and (\ref{eq:NabulaperturbedKKTvectorfield}), this equation is equivalent to 
\begin{equation}
	\nabla F(w) [\Delta w]+F(w)=\mu \hat{e},
\end{equation}
which reduces to the ordinary Newton equation (\ref{eq:OriginalNewtonEquation}) as $\mu \to 0$.
At this point, we can describe a prototype of the Riemannian Interior Point Method (RIPM) in Algorithm \ref{algo:prototype_algo}.

\begin{algorithm}%[H]
	\caption{Prototype Algorithm of RIPM for (\ref{RCOP})}
	\label{algo:prototype_algo}
	\SetAlgoLined

	\KwIn{An initial point $w_0=\left(x_0, y_0, z_0, s_0\right) \in \mathcal{N}$ with $\left(z_0, s_0\right)>0$ and a retraction $\mathrm{R}$ on $\mathcal{M}$. $\hat{\gamma} \in(0,1)$, $\mu_0>0$.}
	\KwOut{Sequence $\left\{w_k\right\} \subset \mathcal{N}$ such that $\left\{w_k\right\} \rightarrow w^*$ and $w^*$ satisfies the KKT conditions (\ref{eq:KKTConditions}).} % 

	Set $k \to 0$\;

	\While{Stopping criterion not satisfied}{
		1. Obtain $\Delta w_{k}=(\Delta x_{k}, \Delta y_{k}, \Delta z_{k},\Delta s_{k}) \in T_{w_k} \mathcal{N}$ by solving the perturbed Newton equation on $T_{w_k} \mathcal{N}$:
		\begin{equation}\label{eq:prototype}
			\nabla F(w_{k}) [\Delta w_{k}]=-F(w_{k})+\mu_{k} \hat{e};
		\end{equation}

		2. Choose $ \gamma_{k} \in [\hat{\gamma},1]$ and compute the step size $\alpha_{k}$ defined by
		\begin{equation}\label{rule:StepSizeA}
			\min \left\{1, \gamma_{k} \min _{i}\left\{-\frac{(s_{k})_{i}}{(\Delta s_{k})_{i}} \mid(\Delta s_{k})_{i}<0\right\},\gamma_{k} \min _{i}\left\{-\frac{(z_{k})_{i}}{(\Delta z_{k})_{i}} \mid(\Delta z_{k})_{i}<0\right\}\right\};
		\end{equation}

		3. Compute the next point as
		$w_{k+1}:=\bar{\mathrm{R}}_{w_k}\left(\alpha_k \Delta w_k\right)$, see (\ref{eq:barR})\;

		4. Choose $0<\mu_{k+1}<\mu_k$\;

		5. $k \to k+1$\;
	}
\end{algorithm}

In the step 2 of Algorithm \ref{algo:prototype_algo}, we just wish to compute a step size $0<\alpha_k \leq 1$ to ensure new point $w_{k+1}$ with $\left(z_{k+1},s_{k+1}\right)>0$. 
There are many schemes to achieve this purpose. 
The scheme in (\ref{rule:StepSizeA}) is simple but sufficient to guarantee the local convergence, as will be proved in Section \ref{sec:local}.


Let us consider Algorithm \ref{algo:prototype_algo} and omit the iteration count $k$.
Given the current point $w \in \mathcal{N}$ with $(z, s) > 0$, for the KKT vector field $F(w)$ in (\ref{eq:KKTVectorField}), we denote its components by $F_x,F_y,F_z,F_s$ in top-to-bottom order, namely,
$F_x:=\operatorname{grad}_x \mathcal{L}(w),F_y:=h(x),F_z:=g(x)+s,F_s:=Z S e.$
By using these symbols and the formulation of $\nabla F(w)$ in (\ref{eq:CovariantDerivativeKKTVectorField}), the \emph{full} (perturbed) Newton equation (\ref{eq:prototype}) defined on $T_w \mathcal{N} \cong T_x \mathcal{M} \times \mathbb{R}^l \times \mathbb{R}^m \times \mathbb{R}^m$ is expanded as:
\begin{equation}\label{eq:FullNewtonEquation}
	\left(\begin{array}{l}
		\operatorname{Hess}_{x} \mathcal{L}(w) [\Delta x]
		+\mathcal{H}_{x} [\Delta y]
		+\mathcal{G}_{x} [\Delta z]\\
		\mathcal{H}_{x}^{*}[\Delta x]\\
		\mathcal{G}_{x}^{*}[\Delta x]+\Delta s\\
		Z \Delta s + S \Delta z
	\end{array}\right)
	=
	\left(\begin{array}{l}
		-F_x\\
		-F_y\\
		-F_z\\
		-F_s+\mu e
	\end{array}\right).
\end{equation}


\begin{remark}
	For a retraction $\mathrm{R}$ on $\mathcal{M}$ and $x \in \mathcal{M}$,
	by $\mathcal{D} \mathrm{R}_{x}\left(0_{x}\right)=\mathrm{id}_{T_{x} \mathcal{M}}$ and the inverse function theorem, there exists a neighborhood $V$ of $0_{x}$ in $T_{x} \mathcal{M}$ such that $ \mathrm{R}_{x} $ is a diffeomorphism on $V$; thus,
	$\mathrm{R}_{x}^{-1}(y)$ is well defined for all $ y \in \mathcal{M} $ sufficiently close to $ x $.
	In this case, $\mathrm{R}_{x}(V) \subset \mathcal{M}$ is called a retractive neighborhood of $x$.
	Furthermore, the existence of a \emph{totally} retractive neighborhood \cite[Theorem 2]{zhu2020riemannian} shows that for any $\bar{x} \in \mathcal{M} $ there is a neighborhood $W$ of $\bar{x}$ such that
	$\mathrm{R}_{x}^{-1}(y)$ is well defined for all $x, y \in W$.
	In what follows, we will suppose that an appropriate neighborhood has been chosen by default for the well-definedness of $\mathrm{R}_x^{-1}(y)$.
\end{remark}


Define the Whitney sum
$
T \mathcal{M} \oplus T \mathcal{M}:=\left\{(\eta, \xi): \eta, \xi \in T_x \mathcal{M}, x \in \mathcal{M} \right\}.
$
A smooth map
$
\mathrm{T} \colon T \mathcal{M} \oplus T \mathcal{M} \to T \mathcal{M}: (\eta, \xi) \mapsto \mathrm{T}_{\eta}(\xi),
$
is called a \emph{vector transport} on $\mathcal{M}$ if there exists an associated retraction $\mathrm{R}$ on $\mathcal{M}$ such that $\mathrm{T}$ satisfies the following properties for all $x \in \mathcal{M}$:
\begin{enumerate}
	\item Associated retraction. $\mathrm{T}_{\eta}\left(\xi\right) \in T_{\mathrm{R}_{x}\left(\eta\right)} \mathcal{M}$
	for all $\eta, \xi \in T_x \mathcal{M}$.	
	\item Consistency. $\mathrm{T}_{0_{x}}\left(\xi\right)=\xi$ for all $\xi \in T_{x} \mathcal{M}$.	
	\item Linearity.
	$\mathrm{T}_{\eta}\left(a \xi+b \zeta\right)=a \mathrm{T}_{\eta}\left(\xi\right)+b \mathrm{T}_{\eta}\left(\zeta\right)$ for all $a, b \in \mathbb{R}$ and $\eta, \xi, \zeta \in T_{x} \mathcal{M}$.
\end{enumerate}
Thus, fixing any $\eta \in T_x \mathcal{M}$, the map
$
\mathrm{T}_\eta \colon T_x \mathcal{M} \to T_{\mathrm{R}_x(\eta)} \mathcal{M}: \xi \mapsto \mathrm{T}_\eta(\xi),
$
is a linear operator.
Additionally, $\mathrm{T}$ is \emph{isometric} if 
$
\langle \mathrm{T}_{\eta} (\xi), \mathrm{T}_{\eta} (\zeta)\rangle =\langle\xi, \zeta\rangle
$
holds, for all $x \in \mathcal{M}$ and all $\xi, \zeta, \eta \in T_{x} \mathcal{M}$.
In other words, for any $\eta \in T_x \mathcal{M}$, the adjoint and the inverse of $\mathrm{T}_{\eta}$ coincide, i.e., $ \mathrm{T}_{\eta}^{*} =  \mathrm{T}_{\eta}^{-1}$.
There are two important classes of vector transport as follows. Let $\mathrm{R}$ be a retraction on $\mathcal{M}$. 
\begin{enumerate}[(1)]
	\item 
	The \emph{differentiated retraction} defined by
	\begin{equation}\label{eq:DifferentiatedRetraction}
		\mathrm{T}_{\eta}(\xi):=\mathcal{D} \mathrm{R}_{x}(\eta)[\xi],  \; \eta, \xi \in T_{x} \mathcal{M}, x \in \mathcal{M}, 
	\end{equation}
	is a valid vector transport \cite[equation (8.6)]{absil2009optimization}.	
	\item
	Given a smooth curve $\gamma \colon [0,1] \to \mathcal{M}$ and $t_0, t_1 \in [0,1]$, the \emph{parallel transport} from the tangent space at $\gamma(t_0)$ to the tangent space at $\gamma(t_1)$ along $\gamma,$
	is a linear operator
	$ \mathrm{P}_\gamma^{t_1 \to t_0} \colon T_{\gamma\left(t_0\right)} \mathcal{M} \rightarrow T_{\gamma\left(t_1\right)} \mathcal{M}$ defined by $\mathrm{P}_\gamma^{t_1 \to t_0}(\xi)=Z\left(t_1\right)$, where $Z$ is the unique parallel vector field such that $Z\left(t_0\right)=\xi$.
	Then, for any $x \in \mathcal{M}, \eta \in T_x \mathcal{M}$, then
	\begin{equation}\label{eq:ParallelTransport}
		\mathrm{T}_{\eta}\left(\xi\right):=\mathrm{P}_\gamma^{1 \to 0} (\xi)
	\end{equation}
	is a valid vector transport \cite[equation (8.2)]{absil2009optimization}, where $\mathrm{P}_\gamma$ denotes the parallel transport along the curve $t \mapsto \gamma(t):=\mathrm{R}_x\left(t \eta\right)$. We often omit the superscript $^{1 \to 0}$ if it is clear from the context.
	In particular, parallel transport is isometric.
\end{enumerate}


Going one degree higher, let us now discuss the Lipschitz continuity of Hessian operators.
Throughout this paper, for a linear operator $\mathcal{A}: \mathcal{E} \rightarrow \mathcal{E}^{\prime}$ between two finite-dimensional normed vector spaces $\mathcal{E}$ and $\mathcal{E}^{\prime}$, the (operator) norm of $\mathcal{A}$ is defined by $\|\mathcal{A}\|:=\sup \left\{\|\mathcal{A} v\|_{\mathcal{E}^{\prime}} : v \in \mathcal{E},\|v\|_{\mathcal{E}}=1\right.$, or, $\left.\|v\|_{\mathcal{E}} \leq 1\right\}.$
The inverse of $\mathrm{T}_{\eta}$ is needed in the following definitions, so we can assume that vector transport $\mathrm{T}$ is isometric, e.g., parallel transport in (\ref{eq:ParallelTransport}). In fact, there are many ways to construct isometric vector transports; see \cite[Section 2.3]{huang2015riemannian}.
\begin{definition}[{\cite[Assumption 3]{huang2015riemannian}}]
	\label{defn:TwiceLipschitzContinuouslyDifferentiable}
	A function $f\colon \mathcal{M} \rightarrow \mathbb{R}$ is \emph{twice Lipschitz continuously differentiable with respect to $\mathrm{T}$ in $\mathcal{U} \subset \mathcal{M}$} if it is twice differentiable and there exists a constant $\kappa>0$ such that, for all $x, y \in \mathcal{U}$, 
	$
	\|\operatorname{Hess} f(y)-\mathrm{T}_{\eta} \operatorname{Hess} f(x) \mathrm{T}_{\eta}^{-1}\| \leq \kappa d(x, y),
	$
	where $\eta=\mathrm{R}_{x}^{-1} y$.
\end{definition}
\begin{lemma}[{\cite[Lemma 4]{huang2015riemannian}}]
	\label{lem:TwiceLipschitzContinuouslyDifferentiable}
	If $f\colon \mathcal{M} \rightarrow \mathbb{R}$ is $ C^3 $, then for any $\bar{x} \in \mathcal{M}$ and any isometric vector transport $\mathrm{T}$, there exists a neighborhood $\mathcal{U}$ of $\bar{x}$ such that $f$ is twice Lipschitz continuously differentiable with respect to $\mathrm{T}$ in $\mathcal{U}$.
\end{lemma}

If the operator, $\operatorname{Hess}f(x)$, above is replaced by a general covariant derivative $\nabla F (x)$, we can get the next results in a similar way.
Lemma \ref{lem:LipCountNabulaF} can be proven in the same way as Lemma \ref{lem:TwiceLipschitzContinuouslyDifferentiable}.
\begin{definition}
	Given a vector field $F$ on $\mathcal{M}$.
	The map $x \mapsto \nabla F(x)$ is \emph{Lipschitz continuous with respect to $\mathrm{T}$ in $\mathcal{U} \subset \mathcal{M}$} if there exists a constant $\kappa>0$ such that, for all $x, y \in \mathcal{U}$, it holds that
	$
	\| \nabla F(y)
	-
	\mathrm{T}_{\eta} \nabla F(x) \mathrm{T}_{\eta}^{-1}
	\| \leq \kappa d(x, y),
	$
	where $\eta=\mathrm{R}_{x}^{-1} y$.
\end{definition}
\begin{lemma}\label{lem:LipCountNabulaF}
	If $F$ is a $C^{2}$ vector field, then
	for any $\bar{x} \in \mathcal{M}$ and any isometric vector transport $\mathrm{T}$, there exists a neighborhood $\mathcal{U}$ of $\bar{x}$ such that the map $x \mapsto \nabla F(x)$ is Lipschitz continuous with respect to $\mathrm{T}$ in $\mathcal{U}$.
\end{lemma}

Notice that in the previous subsection on the definitions of Lipschitz continuity, we used $\|\eta\|$ with $\eta=\mathrm{R}_x^{-1} y$ or $d(x, y)$ to denote the upper bound on the right-hand side. The next lemma shows that the two are not essentially different. When $\mathcal{M}=\mathbb{R}^{n}$, both reduce to $\| x-y \|$.

\begin{lemma}[{\cite[Lemma 2]{huang2015riemannian}}]\label{lem:distR1}
	Let $\mathcal{M}$ be a Riemannian manifold with a retraction $\mathrm{R}$ and let $\bar{x} \in \mathcal{M}$. 
	Then,
	\begin{enumerate}[(i)]
		 \item there exist $a_{0}, a_{1}, \delta_{a_{0}, a_{1}}>0$ such that for all $x$ in a sufficiently small neighborhood of $\bar{x}$ and all $\xi, \eta \in T_{x} \mathcal{M}$ with $\|\xi\|, \|\eta\|  \leq \delta_{a_{0}, a_{1}}$,
		 one has
		 $
		 a_{0}\|\xi-\eta\| \leq d(\mathrm{R}_{x}(\eta), \mathrm{R}_{x}(\xi)) \leq a_{1}\|\xi-\eta\|.
		 $	
		 In particular,
		 $
		 a_{0}\|\xi\| \leq d(x, \mathrm{R}_{x}(\xi)) \leq a_{1}\|\xi\|
		 $
		 when $\eta=0$;

		 \item
		 there exist $a_{0},a_{1}>0$ such that for all $x$ in a sufficiently small neighborhood of $\bar{x}$, one has
		 $
		 a_{0}\|\xi\| \leq d(x,\bar{x}) \leq a_{1}\|\xi\| \text { where } \xi=\mathrm{R}_{\bar{x}}^{-1}(x). 
		 $
	\end{enumerate}
\end{lemma}

The next lemma is the fundamental theorem of calculus in the Riemannian case.
\begin{lemma}[{\cite[Lemma 8]{huang2015riemannian}}]\label{lem:FundamentalTheoremOfCalculusRiemannian}
	Let $F$ be a $C^{1}$ vector field and $\bar{x} \in \mathcal{M}$. 
	Then there exist a neighborhood $\mathcal{U}$ of $\bar{x}$ and a constant $c_{1} \geq 0$ such that for all $x, y \in \mathcal{U}$,
	\begin{equation*}
	\left\| \mathrm{P}_{\gamma}^{0 \to 1} [F(y)]-F(x)-\int_{0}^{1} \mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} [\eta] \mathrm{d} t \right\| 
	\leq c_{1} \|\eta\|^{2},
	\end{equation*}
	where $\eta=\mathrm{R}_{x}^{-1}(y)$ and $\mathrm{P}_{\gamma}$ is the parallel transport along the curve $\gamma(t):=\mathrm{R}_{x}\left(t \eta\right)$.
	Moreover, if $\mathrm{R}=\operatorname{Exp}$, then indeed $c_1=0$ above (see \cite[equation (2.4)]{ferreira2002kantorovich}).
\end{lemma}


\begin{lemma}[{\cite[Lemma 3.2]{fernandes2017superlinear}}]\label{lem:nonsingular}
	Given a vector field $F$ on $\mathcal{M}$.
	If the map $p \mapsto \nabla F(p)$ is continuous at $p^{*}$ and $\nabla F(p^{*})$ is nonsingular, 
	then there exist a neighborhood $\mathcal{U}$ of $p^{*}$ and a constant $\Xi > 0$ such that, for all $p \in \mathcal{U}$, $\nabla F(p)$ is nonsingular and $\left\|\nabla F(p)^{-1}\right\| \leq \Xi$.
\end{lemma}
\begin{lemma}[{\cite[Lemma 14.5]{gallivan2012riemannian}}]\label{lem:dist_zero}
	Let $F$ be a  $C^2$ vector field on $\mathcal{M}$ and $p^{*} \in \mathcal{M}$. If $ F(p^{*})=0 $ and $\nabla F(p^{*}) $ is nonsingular, then there exist a neighborhood $\mathcal{U}$ of $p^{*}$ and constants $c_{3}, c_{4} > 0$ such that, for all $p \in \mathcal{U}$, $ c_{3} d(p, p^{*}) \leq \|F(p)\| \leq c_{4} d(p, p^{*}).$
\end{lemma}


Here, for any two nonnegative sequences $\left\{u_{k}\right\}$ and $\left\{v_{k}\right\}$, we write $u_{k}=O(v_{k})$ if there is a constant $M >0$ such that
$u_{k}\leq M v_{k}$
for all sufficiently large $k$; and we write
$u_{k}=o(v_{k})$
if $v_{k}>0$ and the sequence of ratios $\{u_{k} / v_{k}\} $ approaches zero.


\begin{algorithm}%[H]
	\caption{Perturbed Damped Riemannian Newton Method for (\ref{eq:Singularity})}
	\label{algo:PerturbedDampedNewtonMethod}
	\SetAlgoLined

	\KwIn{A vector field $F \in \mathfrak{X}(\mathcal{M})$, an initial point $p_0 \in \mathcal{M}$ and a retraction $\mathrm{R}$ on $\mathcal{M}$. Set $\mu_0>0$.}
	\KwOut{Sequence $\{p_k\} \subset \mathcal{M}$ such that $\left\{p_k\right\} \rightarrow p^*$ and $F(p^{*})=0_{p^{*}}$.}

	Set $k \to 0$\;

	\While{Stopping criterion not satisfied}{
		1. Obtain $\xi_k \in T_{p_k}\mathcal{M}$ by solving the perturbed Newton equation:
		\begin{equation}
			\nabla F(p_{k}) [\xi_k] = - F(p_{k}) + \mu_{k} \hat{e};
		\end{equation}

		2. Choose a (damped) step size $ 0<\alpha_{k} \leq 1$\;

		3. Compute the next point as $p_{k+1}:=\mathrm{R}_{p_{k}} (\alpha_{k} \xi_k)$\;

		4. Choose $0<\mu_{k+1}<\mu_k$\;

		5. $k \to k + 1$\;
	}
\end{algorithm}


\begin{assumptions}[leftmargin=9mm]
	\item There exists $p^{*} \in \mathcal{M}$ such that $F(p^{*})=0_{p^{*}}$;
	\label{A1}
	\item The covariant derivative $\nabla F (p^{*})$ is nonsingular;
	\label{A2}
%	\item The map $p \mapsto \nabla F(p) $ is Lipschitz continuous with respect to on a neighborhood of $p^{*}$;
%	\label{A3}
	\item The vector field $F$ is $C^2$.
	\label{A3}
\end{assumptions}


\begin{lemma}\label{lem:gamma_alpha}
	Consider the Algorithm \ref{algo:prototype_algo} for solving the problem (\ref{RCOP}).  
	Let \ref{B1} and \ref{B4} hold at some $w^{*}=(x^{*}, y^{*}, z^{*}, s^{*})$ and $ \alpha_{k} $ be as in (\ref{rule:StepSizeA}). 
	Define a constant,
	\begin{equation*}
	\Pi := 2 \max \left\{\max _{i}\left\{
	1/(s^{*})_{i}
	\mid (s^{*})_{i}>0\right\}, \max _{i}\left\{
	1/(z^{*})_{i}
	\mid (z^{*})_{i}>0\right\}\right\}.
	\end{equation*}
	For $\gamma_{k} \in(0,1)$, if
	$
	\Pi \left\| \Delta w_{k}\right\| \leq \gamma_{k},
	$
	then
	$
	0  \leq 1-\alpha_{k} \leq
	(1-\gamma_{k})+\Pi \left\| \Delta w_{k}\right\|.
	$
\end{lemma}

