\begin{lemma}\label{lem:R1est}
	Let $F$ be a $ C^2 $ vector field and $\bar{x}\in\mathcal{M}$. Then there exist a neighborhood $\mathcal{U}$ of $\bar{x}$ and a constant $c_{2}>0$ such that for all $x \in \mathcal{U}$,
	\begin{equation*}
	\left\|\mathrm{P}_{\gamma}^{0 \to 1} [F(x)]-F(\bar{x})-\nabla F(\bar{x}) [\eta] 
	\right\|
	 \leq c_{2} d^{2}(\bar{x} , x),
	\end{equation*}
	where $\eta=\mathrm{R} _{\bar{x}}^{-1} x$ and $\mathrm{P}_{\gamma}$ is the parallel transport along the curve $\gamma(t):=\mathrm{R}_{\bar{x}}(t \eta)$.
\end{lemma}

\begin{proof} 
Let $LHS:=\|\mathrm{P}_{\gamma}^{0 \to 1} [F(x)]-F(\bar{x})-\nabla F(\bar{x}) [\eta] \|.$ It follows that
\begin{equation*}
		\begin{aligned}
			LHS
			& \leq
			\left\|\mathrm{P}_{\gamma}^{0 \to 1} [F(x)]-F(\bar{x})
			-\int_{0}^{1} \mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} [\eta] \mathrm{d} t  \right\| \\
			& \quad +
			\left\|\int_{0}^{1} \mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} [\eta] \mathrm{d} t -\nabla F(\bar{x}) [\eta] \right\| \\
			&\leq 
			c_{1} \|\eta\|^{2} +
			\Big\|
			\int_{0}^{1}\left(\mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} -\nabla F(\bar{x})\right)
			[\eta] \mathrm{d} t\Big\|.
			\text{ (by Lemma \ref{lem:FundamentalTheoremOfCalculusRiemannian})}
		\end{aligned}
\end{equation*}
Let
$\theta := \left\| \int_{0}^{1}\left(\mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} -\nabla F(\bar{x})\right)
[\eta] \mathrm{d} t \right\|$.
Note that
\begin{align*}
	\theta 
	&\leq 
	\int_{0}^{1} 
	\left\|
	\mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} -\nabla F(\bar{x})
	\right\|
	\left\| \eta \right\|
	\mathrm{d} t \\
	&\leq  
	\int_{0}^{1} 
	c_{0} d(\bar{x}, \mathrm{R}_{\bar{x}}(t \eta))
	\left\| \eta \right\|
	\mathrm{d} t	\text{ (by Lemma \ref{lem:LipCountNabulaF})} \\
	&\leq   
	\int_{0}^{1} 
	c_{0} a_{1}t \|\eta\|
	\left\| \eta \right\|
	\mathrm{d} t 	
	= 
	\frac{1}{2} 
	c_{0} a_{1} \|\eta\|^{2}. 	
	\text{ (by (i) of Lemma \ref{lem:distR1})}
\end{align*}
Combining the above results yields
$$
LHS
\leq (c_{1}+ \frac{1}{2} 
c_{0} a_{1})
\|\eta\|^{2}
\leq  
(c_{1}+ \frac{1}{2} 
c_{0} a_{1})  / a_{0}^{2}
d^{2}(\bar{x} , x),
$$
where the last inequality comes from (ii) of Lemma \ref{lem:distR1}. Letting $c_{2}:= (c_{1}+ \frac{1}{2} 
c_{0} a_{1})  / a_{0}^{2} $ completes the proof.
\end{proof}

source_units.raw_tex:
In this paper, we consider the following Riemannian Constrained Optimization Problem (RCOP):
\begin{equation}\tag{RCOP} \label{RCOP} 
	\begin{array}{ll}
		\underset{x \in \mathcal{M}}{\min} & f(x) \\
		\text { s.t. } & h(x)=0, \text{ and }  g(x) \leq 0,\\
	\end{array}
\end{equation}
where $\mathcal{M}$ is a connected, complete $d$-dimensional Riemannian manifold and $f \colon \mathcal{M}\to \mathbb{R}, h\colon\mathcal{M}\to \mathbb{R}^{l}$, and $g\colon\mathcal{M}\to \mathbb{R}^{m}$ are smooth functions.

\subsection{Riemannian Newton Method}\label{subsec:RiemannianNewton}

The Newton method is a powerful tool for finding the zeros of nonlinear functions in the Euclidean setting.
The generalized Newton method has been studied in the Riemannian setting; it aims to find a \emph{singularity} for the vector field $F \in \mathfrak{X}(\mathcal{M})$, i.e., a point $p \in \mathcal{M}$ such that,
\begin{equation}\label{eq:Singularity}
	F(p)=0_{p} \in T_p \mathcal{M}.
\end{equation}
Let $\nabla$ be the Levi-Civita connection on $\mathcal{M}$, i.e., the unique symmetric connection compatible with the Riemannian metric.
The covariant derivative $\nabla F$ assigns each point $p \in \mathcal{M}$ a linear operator $\nabla F(p)\colon T_{p}\mathcal{M}\to T_{p}\mathcal{M}$. 
In particular, the Riemannian Hessian of $f \in \mathfrak{F}(\mathcal{M})$ at $p$ is a self-adjoint operator on $T_{p} \mathcal{M}$, defined as $\operatorname{Hess} f(p):=\nabla (\operatorname{grad}f)(p).$

In this section, we will give a comprehensive interpretation of the Riemannian interior point method.
Following common usage in the interior-point literature, big letters denote the associated diagonal matrix, e.g., $Z =\operatorname{diag}(z_{1}, \ldots, z_{m})$ with $z \in \mathbb{R}^{m}$. $e$ denotes the all-ones vector, and $0$ stands for zero vector/matrix with proper dimensions.

\subsection{KKT Vector Field and Its Covariant Derivative}

The Lagrangian function of (\ref{RCOP}) is
\begin{equation*}
	\mathcal{L}(x, y, z):=f(x)+\sum_{i=1}^l y_i h_i(x)+\sum_{i=1}^m z_i g_i(x),
\end{equation*}
where $y \in \mathbb{R}^l$ and $z \in \mathbb{R}^m$ are Lagrange multipliers corresponding to the equality and
inequality constraints, respectively.
With respect to the variable $x$, $\mathcal{L}(\cdot, y, z)$ is a real-valued function defined on $\mathcal{M}$, and its Riemannian gradient is
\begin{equation*}
\operatorname{grad}_{x} \mathcal{L}(x, y, z)=\operatorname{grad} f(x) + \sum_{i =1 }^{l} y_{i} \operatorname{grad} h_{i}(x) + \sum_{i =1 }^{m} z_{i} \operatorname{grad} g_{i}(x),
\end{equation*}
where $\{\operatorname{grad} h_{i}(x)\}_{i=1}^{l}$ and $ \{\operatorname{grad} g_{i}(x)\}_{i=1}^{m}$ are the gradients of the component functions of $h$ and $g$.

The Riemannian KKT conditions (e.g., see \cite[Definition 2.3]{liu2020simple} or \cite{yang2014optimality}) for (\ref{RCOP}) are given by
\begin{equation}\label{eq:KKTConditions}
	\operatorname{grad}_{x} \mathcal{L}(x, y, z) =0_{x}; \;
	h(x) =0 ,
	g(x) \leq 0 , 
	z  \geq 0; \;
	Z g(x) =0.
\end{equation}

Note that for $\xi=\left(\xi_x, \xi_y, \xi_z, \xi_s\right) \in T_{w} \mathcal{N} $,
\begin{equation}\label{eq:barR}
	\bar{\mathrm{R}}_{w}(\xi):=(\mathrm{R}_{x}(\xi_{x}), y+\xi_{y}, z+\xi_{z}, s+\xi_{s})
\end{equation}
is a well-defined retraction on the product manifold $\mathcal{N}$ as long as $\mathrm{R}$ is a retraction on $\mathcal{M}$.

Now, we aim to find a singularity of the KKT vector field $F$ on $\mathcal{N}$ under some nonnegative constraints $(z,s) \geq 0$.
If the Riemannian Newton method is to be applied to (\ref{eq:KKTVectorField}), we must formulate the covariant derivative of $F$ at an arbitrary $w \in \mathcal{N}$. Before that, we need some new symbols.
Fixing a point $x \in \mathcal{M}$, we can define two linear operators $\mathcal{H}_{x}\colon \mathbb{R}^{l} \rightarrow T_{x} \mathcal{M}$ and $\mathcal{G}_{x}\colon \mathbb{R}^{m} \rightarrow T_{x} \mathcal{M}$ by
\begin{equation}\label{defn:HxGx}
	\mathcal{H}_x [v]:=\sum_{i=1}^l v_i \operatorname{grad} h_i(x), \quad \mathcal{G}_x [u]:=\sum_{i=1}^m u_i \operatorname{grad} g_i(x),
\end{equation}
respectively.
Then, for $\mathcal{H}_{x}$, its adjoint operator $\mathcal{H}_x^*\colon T_x \mathcal{M} \rightarrow \mathbb{R}^l$ is given by
\begin{equation*}
	\mathcal{H}_x^* [\xi]=\left(\left\langle\operatorname{grad} h_1(x), \xi\right\rangle_x, \cdots,\left\langle\operatorname{grad} h_l(x), \xi\right\rangle_x\right)^T.
\end{equation*}
Also, $\mathcal{G}_x^*\colon T_x \mathcal{M} \rightarrow \mathbb{R}^m$ with $\mathcal{G}_x^* [\xi]=\left(\left\langle\operatorname{grad} g_1(x), \xi\right\rangle_x, \cdots,\left\langle\operatorname{grad} g_m(x), \xi\right\rangle_x\right)^T$.

	\item {Existence.} There exists $w^*=(x^{*}, y^{*}, z^{*}, s^{*})$ satisfying the Riemannian KKT conditions (\ref{eq:KKTConditions}). Here, we introduce the slack variables $s^{*}:=-g(x^{*})$.
	\label{B1}	
%	\item {Smoothness of $ C^{2} $.} The functions $f, g,$ and $h$ are $ C^{2} $ on $\mathcal{M}$.
%	\label{B2}

	\item {Second-order sufficiency.}
	$\left \langle\operatorname{Hess}_{x} \mathcal{L}(w^{*})[\xi], \xi\right\rangle>0$ for all nonzero $\xi \in T_{x^{*}}\mathcal{M}$ \\ satisfying $\left\langle\xi, \operatorname{grad} h_{i}(x^{*})\right\rangle=0 $ for $i=1,\dots,l,$ and
	$\left\langle\xi, \operatorname{grad} g_{i}(x^{*})\right\rangle=0$ for $ i \in \mathbb{A}(x^{*})$. 
	\label{B5}
\end{assumptions}

Applying the Riemannian Newton method directly to the KKT vector field $F: \mathcal{N} \rightarrow T \mathcal{N}$ results in the following Newton equation (see (\ref{eq:StandardNewtonEquation}) without iteration count $k$) at each iteration:
\begin{equation}\label{eq:OriginalNewtonEquation}
	\nabla F(w) [\Delta w]+F(w)=0.
\end{equation}
As with the usual interior point method in the Euclidean setting, once the iterates reach the boundary of the feasible region, they are forced to stick to it \cite[P6]{wright1997primal}.
For the iterates to maintain a sufficient distance from the boundary, we introduce a perturbed complementary equation with some barrier parameter $\mu>0$ and define the \textit{perturbed KKT vector field}:

\begin{equation}\label{eq:perturbedKKTvectorfield}
	F_{\mu}(w):=F(w)-\mu \hat{e}, \text { and } \hat{e}:=\hat{e}(w):=\left(0_x, 0,0, e\right).
\end{equation}
Notice that the perturbation term $\hat{e}$, indeed, is a special vector field on $\mathcal{N}$, not a constant, because $0_x$ is essentially dependent on $w$ and/or $x$.

In fact, the covariant derivative of the perturbed KKT vector field is the same as that of the original. From the linearity of the connection $\nabla$, for any $w \in \mathcal{N}$ and any $\mu>0$, we have 
\begin{equation}\label{eq:NabulaperturbedKKTvectorfield}
	\nabla F_{\mu}(w)=\nabla F(w)-\mu \nabla \hat{e}(w)=\nabla F(w),
\end{equation}
where the last equity comes from $\nabla \hat{e}(w) [\Delta w]=\left(0_x, 0,0,0\right)$ for all $\Delta w \in T_w \mathcal{N}$.
Applying the Riemannian Newton method to perturbed KKT vector field $F_{\mu}(w)$ yields the \emph{perturbed Newton equation}: $\nabla F_{\mu}(w) [\Delta w]+F_{\mu}(w)=0$. 
From (\ref{eq:perturbedKKTvectorfield}) and (\ref{eq:NabulaperturbedKKTvectorfield}), this equation is equivalent to 
\begin{equation}
	\nabla F(w) [\Delta w]+F(w)=\mu \hat{e},
\end{equation}
which reduces to the ordinary Newton equation (\ref{eq:OriginalNewtonEquation}) as $\mu \to 0$.
At this point, we can describe a prototype of the Riemannian Interior Point Method (RIPM) in Algorithm \ref{algo:prototype_algo}.

\begin{algorithm}%[H]
	\caption{Prototype Algorithm of RIPM for (\ref{RCOP})}
	\label{algo:prototype_algo}
	\SetAlgoLined

	\KwIn{An initial point $w_0=\left(x_0, y_0, z_0, s_0\right) \in \mathcal{N}$ with $\left(z_0, s_0\right)>0$ and a retraction $\mathrm{R}$ on $\mathcal{M}$. $\hat{\gamma} \in(0,1)$, $\mu_0>0$.}
	\KwOut{Sequence $\left\{w_k\right\} \subset \mathcal{N}$ such that $\left\{w_k\right\} \rightarrow w^*$ and $w^*$ satisfies the KKT conditions (\ref{eq:KKTConditions}).} % 

	Set $k \to 0$\;

	\While{Stopping criterion not satisfied}{
		1. Obtain $\Delta w_{k}=(\Delta x_{k}, \Delta y_{k}, \Delta z_{k},\Delta s_{k}) \in T_{w_k} \mathcal{N}$ by solving the perturbed Newton equation on $T_{w_k} \mathcal{N}$:
		\begin{equation}\label{eq:prototype}
			\nabla F(w_{k}) [\Delta w_{k}]=-F(w_{k})+\mu_{k} \hat{e};
		\end{equation}

		2. Choose $ \gamma_{k} \in [\hat{\gamma},1]$ and compute the step size $\alpha_{k}$ defined by
		\begin{equation}\label{rule:StepSizeA}
			\min \left\{1, \gamma_{k} \min _{i}\left\{-\frac{(s_{k})_{i}}{(\Delta s_{k})_{i}} \mid(\Delta s_{k})_{i}<0\right\},\gamma_{k} \min _{i}\left\{-\frac{(z_{k})_{i}}{(\Delta z_{k})_{i}} \mid(\Delta z_{k})_{i}<0\right\}\right\};
		\end{equation}

		3. Compute the next point as
		$w_{k+1}:=\bar{\mathrm{R}}_{w_k}\left(\alpha_k \Delta w_k\right)$, see (\ref{eq:barR})\;

		4. Choose $0<\mu_{k+1}<\mu_k$\;

		5. $k \to k+1$\;
	}
\end{algorithm}

\begin{lemma}[{\cite[Lemma 4]{huang2015riemannian}}]
	\label{lem:TwiceLipschitzContinuouslyDifferentiable}
	If $f\colon \mathcal{M} \rightarrow \mathbb{R}$ is $ C^3 $, then for any $\bar{x} \in \mathcal{M}$ and any isometric vector transport $\mathrm{T}$, there exists a neighborhood $\mathcal{U}$ of $\bar{x}$ such that $f$ is twice Lipschitz continuously differentiable with respect to $\mathrm{T}$ in $\mathcal{U}$.
\end{lemma}

\begin{lemma}\label{lem:LipCountNabulaF}
	If $F$ is a $C^{2}$ vector field, then
	for any $\bar{x} \in \mathcal{M}$ and any isometric vector transport $\mathrm{T}$, there exists a neighborhood $\mathcal{U}$ of $\bar{x}$ such that the map $x \mapsto \nabla F(x)$ is Lipschitz continuous with respect to $\mathrm{T}$ in $\mathcal{U}$.
\end{lemma}

The next lemma is the fundamental theorem of calculus in the Riemannian case.
\begin{lemma}[{\cite[Lemma 8]{huang2015riemannian}}]\label{lem:FundamentalTheoremOfCalculusRiemannian}
	Let $F$ be a $C^{1}$ vector field and $\bar{x} \in \mathcal{M}$. 
	Then there exist a neighborhood $\mathcal{U}$ of $\bar{x}$ and a constant $c_{1} \geq 0$ such that for all $x, y \in \mathcal{U}$,
	\begin{equation*}
	\left\| \mathrm{P}_{\gamma}^{0 \to 1} [F(y)]-F(x)-\int_{0}^{1} \mathrm{P}_{\gamma}^{0 \to t} \nabla F(\gamma(t)) \mathrm{P}_{\gamma}^{t \to 0} [\eta] \mathrm{d} t \right\| 
	\leq c_{1} \|\eta\|^{2},
	\end{equation*}
	where $\eta=\mathrm{R}_{x}^{-1}(y)$ and $\mathrm{P}_{\gamma}$ is the parallel transport along the curve $\gamma(t):=\mathrm{R}_{x}\left(t \eta\right)$.
	Moreover, if $\mathrm{R}=\operatorname{Exp}$, then indeed $c_1=0$ above (see \cite[equation (2.4)]{ferreira2002kantorovich}).
\end{lemma}

\begin{lemma}[{\cite[Lemma 3.2]{fernandes2017superlinear}}]\label{lem:nonsingular}
	Given a vector field $F$ on $\mathcal{M}$.
	If the map $p \mapsto \nabla F(p)$ is continuous at $p^{*}$ and $\nabla F(p^{*})$ is nonsingular, 
	then there exist a neighborhood $\mathcal{U}$ of $p^{*}$ and a constant $\Xi > 0$ such that, for all $p \in \mathcal{U}$, $\nabla F(p)$ is nonsingular and $\left\|\nabla F(p)^{-1}\right\| \leq \Xi$.
\end{lemma}

\begin{lemma}[{\cite[Lemma 14.5]{gallivan2012riemannian}}]\label{lem:dist_zero}
	Let $F$ be a  $C^2$ vector field on $\mathcal{M}$ and $p^{*} \in \mathcal{M}$. If $ F(p^{*})=0 $ and $\nabla F(p^{*}) $ is nonsingular, then there exist a neighborhood $\mathcal{U}$ of $p^{*}$ and constants $c_{3}, c_{4} > 0$ such that, for all $p \in \mathcal{U}$, $ c_{3} d(p, p^{*}) \leq \|F(p)\| \leq c_{4} d(p, p^{*}).$
\end{lemma}

\begin{algorithm}%[H]
	\caption{Perturbed Damped Riemannian Newton Method for (\ref{eq:Singularity})}
	\label{algo:PerturbedDampedNewtonMethod}
	\SetAlgoLined

	\KwIn{A vector field $F \in \mathfrak{X}(\mathcal{M})$, an initial point $p_0 \in \mathcal{M}$ and a retraction $\mathrm{R}$ on $\mathcal{M}$. Set $\mu_0>0$.}
	\KwOut{Sequence $\{p_k\} \subset \mathcal{M}$ such that $\left\{p_k\right\} \rightarrow p^*$ and $F(p^{*})=0_{p^{*}}$.}

	Set $k \to 0$\;

	\While{Stopping criterion not satisfied}{
		1. Obtain $\xi_k \in T_{p_k}\mathcal{M}$ by solving the perturbed Newton equation:
		\begin{equation}
			\nabla F(p_{k}) [\xi_k] = - F(p_{k}) + \mu_{k} \hat{e};
		\end{equation}

		2. Choose a (damped) step size $ 0<\alpha_{k} \leq 1$\;

		3. Compute the next point as $p_{k+1}:=\mathrm{R}_{p_{k}} (\alpha_{k} \xi_k)$\;

		4. Choose $0<\mu_{k+1}<\mu_k$\;

		5. $k \to k + 1$\;
	}
\end{algorithm}

\begin{assumptions}[leftmargin=9mm]
	\item There exists $p^{*} \in \mathcal{M}$ such that $F(p^{*})=0_{p^{*}}$;
	\label{A1}
	\item The covariant derivative $\nabla F (p^{*})$ is nonsingular;
	\label{A2}
%	\item The map $p \mapsto \nabla F(p) $ is Lipschitz continuous with respect to on a neighborhood of $p^{*}$;
%	\label{A3}
	\item The vector field $F$ is $C^2$.
	\label{A3}
\end{assumptions}

\begin{lemma}\label{lem:gamma_alpha}
	Consider the Algorithm \ref{algo:prototype_algo} for solving the problem (\ref{RCOP}).  
	Let \ref{B1} and \ref{B4} hold at some $w^{*}=(x^{*}, y^{*}, z^{*}, s^{*})$ and $ \alpha_{k} $ be as in (\ref{rule:StepSizeA}). 
	Define a constant,
	\begin{equation*}
	\Pi := 2 \max \left\{\max _{i}\left\{
	1/(s^{*})_{i}
	\mid (s^{*})_{i}>0\right\}, \max _{i}\left\{
	1/(z^{*})_{i}
	\mid (z^{*})_{i}>0\right\}\right\}.
	\end{equation*}
	For $\gamma_{k} \in(0,1)$, if
	$
	\Pi \left\| \Delta w_{k}\right\| \leq \gamma_{k},
	$
	then
	$
	0  \leq 1-\alpha_{k} \leq
	(1-\gamma_{k})+\Pi \left\| \Delta w_{k}\right\|.
	$
\end{lemma}

\begin{theorem}\label{prop:non}
	If the standard Riemannian assumptions \ref{B1}-\ref{B5} hold at some point $w^{*}$,
	then the operator $\nabla F(w^{*})$ in (\ref{eq:CovariantDerivativeKKTVectorField}) is nonsingular.
\end{theorem}

\begin{proof}
This proof omits all the asterisks of the variables. Define $ \mathbb{E}:=\{1,\dots,l\}$ and $\mathbb{I}:=\{1,\dots,m\} $. Take some $w=(x, y, z, s) \in \mathcal{N} $ satisfying \ref{B1}-\ref{B5}, then we have $ s_{i} = -g_{i}(x)$ and $z_{i} s_{i} = 0$ for all $ i \in \mathbb{I}$. For short, let $\mathbb{A}:=\mathbb{A}(x) \subset \mathbb{I} $. 
Suppose that $\nabla {F}(w) [\Delta w] =0$ for some $\Delta w = (\Delta x, \Delta y, \Delta z, \Delta s) \in T_{w} \mathcal{N} \cong T_x \mathcal{M} \times \mathbb{R}^l \times \mathbb{R}^m \times \mathbb{R}^m$.
$\Delta y_i$ denotes the components of the vector $\Delta y$, as do $\Delta z_i$, $\Delta s_i$.
To prove its nonsingularity, we will show that $ \Delta w=0$.
Expanding the equation $\nabla {F}(w) [\Delta w] =0$ gives
\begin{equation}\label{13}
	\left\{
	\begin{aligned}
		0&= \operatorname{Hess}_{x} \mathcal{L}(w) [\Delta x]
		+\sum_{i\in \mathbb{E}} \Delta y_{i} \operatorname{grad} h_{i}(x)
		+\sum_{i\in \mathbb{I}} \Delta z_{i} \operatorname{grad} g_{i}(x),\\
		0&=\left\langle\operatorname{grad}h_{i}(x), \Delta x\right\rangle, \text { for all } i\in \mathbb{E},\\
		0&=\left\langle\operatorname{grad} g_{i}(x), \Delta x\right\rangle + \Delta s_{i}, \text { for all } i\in \mathbb{I}, \\
		0&=z_{i} \Delta s_{i} + s_{i} \Delta z_{i}, \text { for all } i \in \mathbb{I}. 
	\end{aligned}
	\right.
\end{equation}

\begin{lemma}\label{lem:R1est}
