\begin{proof}
By \ref{A2}-\ref{A3}, Lemma \ref{lem:LipCountNabulaF} and Lemma \ref{lem:nonsingular}, we can let $p_{k} $ be sufficiently close to $p^{*}$ such that $\nabla F(p_{k})$ is nonsingular, and
$\left\|\nabla F(p_{k})^{-1}\right\| \leq \Xi$ for some constant $\Xi$.
Then, the next iterate point,
\begin{equation*}
p_{k+1}:=\mathrm{R}_{p_{k}}[\alpha_{k} \nabla F(p_{k})^{-1}(-F(p_{k})+\mu_{k} \hat{e})],
\end{equation*}

is well defined in Algorithm \ref{algo:PerturbedDampedNewtonMethod}, and it follows from $ p^{*}=\mathrm{R}_{p_{k}}(\eta) $ with $ \eta := \mathrm{R}_{p_{k}}^{-1} p^{*} $ and (i) of Lemma \ref{lem:distR1} that
\begin{align}
	d(p_{k+1} , p^{*})
	&\leq
	a_{1}
	\| \eta - \alpha_{k} \nabla F(p_{k})^{-1}(-F(p_{k})+\mu_{k} \hat{e}) \| \notag \\
	&=
	a_{1}  
	\|\eta + \alpha_{k} \nabla F(p_{k})^{-1}(F(p_{k})-\mu_{k} \hat{e})\|. \label{eq:1114}
\end{align}

Combining the above with (\ref{eq:1114}), we conclude that
\begin{equation}\label{77}
	d(p_{k+1} , p^{*}) \leq \kappa_{1}(1-\alpha_{k}) d(p_{k} , p^{*}) 
	+ \kappa_{2} d^{2}(p_{k} , p^{*})
	+ \kappa_{3} \mu_{k}
\end{equation}
for some positive constants $ \kappa_{1},\kappa_{2},\kappa_{3}$.

On the other hand, by Lemma \ref{lem:dist_zero}, we have
\begin{equation}\label{eq:LipFbigoh}
	\left\|F(p_{k})\right\|=O(d(p_{k}, p^{*})).
\end{equation}

\begin{theorem}[Local convergence of prototype Algorithm \ref{algo:prototype_algo}]\label{thm:LocalConvergence}
	Consider the Algorithm \ref{algo:prototype_algo} for solving the problem (\ref{RCOP}).  
	Let \ref{B1}-\ref{B5} hold at some $w^{*}$.
	Choose parameters $\mu_k, \gamma_k$ as follows;
	then there exists a constant $\delta>0$ such that, for all
	$
	w_{0} \in\mathcal{N}
	$
	with $d(w_{0} , w^{*})<\delta,$
	the sequence $\left\{w_{k}\right\}$ is well defined. Furthermore,
	\begin{enumerate}[(1)]
		\item if we choose $\mu_{k}=o(\left\|F(w_{k})\right\|)$ and $\gamma_{k} \to 1$, then $w_k \to w^*$ superlinearly;	
		\item if we choose $\mu_{k}=O(\left\|F(w_{k})\right\|^{2})$
		and $1-\gamma_{k}=O(\left\|F(w_{k})\right\|)$, then $w_k \to w^*$ quadratically.
	\end{enumerate}
\end{theorem}
